const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const assert = require('node:assert/strict');
const run = require('node:util').promisify(require('node:child_process').execFile);
const root = process.cwd();
require(path.join(root, 'test/test-env')).applyTestEnv();
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'r11-retarget-'));
Object.assign(process.env, { HOME: home, TMUX_TMPDIR: path.join(home, 'tmux'), PI_DISH_INDEX_SYNC_BUDGET: '1000' });
fs.mkdirSync(process.env.TMUX_TMPDIR);
const native = 'route-hit';
const encoded = '~sk1_' + Buffer.from(JSON.stringify(['omp', native])).toString('base64url');
for (const [harness, name] of [['pi', 'Pi peer'], ['omp', 'OMP target']]) {
  const dir = path.join(home, `.${harness}`, 'agent/sessions/project');
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, native + '.jsonl'), [
    { type: 'session', version: 3, id: native, cwd: home, timestamp: '2026-09-05T09:07:03.291Z' },
    { type: 'session_info', name },
    { type: 'message', id: 'u1', message: { role: 'user', content: [{ type: 'text', text: name }], timestamp: '2026-09-05T09:07:04.000Z' } },
  ].map(JSON.stringify).join('\n') + '\n');
}
for (const version of ['before','after']) {
  const skills = path.join(home, version, 'skills');
  fs.mkdirSync(path.join(skills, 'lib'), { recursive: true });
  fs.mkdirSync(path.join(skills, 'pi-dish-sessions/scripts'), { recursive: true });
  fs.copyFileSync(version === 'before' ? '/tmp/r11-baseline-client.js' : path.join(root, 'skills/lib/pi-dish-client.js'), path.join(skills, 'lib/pi-dish-client.js'));
  fs.copyFileSync(path.join(root, 'skills/pi-dish-sessions/scripts/pi-dish-sessions.js'), path.join(skills, 'pi-dish-sessions/scripts/pi-dish-sessions.js'));
}
const server = require(path.join(root, 'server'));
(async () => {
  try {
    if (!server.listening) await new Promise(resolve => server.once('listening', resolve));
    const base = `http://127.0.0.1:${server.address().port}`;
    let catalog;
    for (let i = 0; i < 100; i++) {
      catalog = await (await fetch(base + '/api/sessions')).json();
      if (!catalog.indexing && catalog.previous.length === 2) break;
      await new Promise(resolve => setTimeout(resolve, 50));
    }
    assert.deepEqual(catalog.previous.map(s => s.id).sort(), [native, encoded].sort());
    const host = await (await fetch(base + '/api/host')).json();
    assert.equal(host.capabilities.refAliases, true);
    const outcomes = [];
    for (const version of ['before','after']) {
      const skills = path.join(home, version, 'skills');
      const cli = path.join(skills, 'pi-dish-sessions/scripts/pi-dish-sessions.js');
      const client = require(path.join(skills, 'lib/pi-dish-client.js'));
      const ids = catalog.previous.map(s => s.id);
      const stableRef = client.stableSessionRef(encoded, ids);
      const invoke = args => run(process.execPath, [cli, ...args, '--url', base], { env: process.env, cwd: home });
      const listed = (await invoke(['list'])).stdout;
      const targetRow = listed.split('\n').find(line => line.includes('\tOMP target\t'));
      assert.ok(targetRow, listed);
      const printedRef = targetRow.split('\t')[0];
      assert.equal(printedRef, stableRef);
      const resolved = JSON.parse((await invoke(['resolve', printedRef, '--json'])).stdout);
      const direct = await (await fetch(base + '/api/sessions/resolve?id=' + encodeURIComponent(printedRef))).json();
      const clientSide = await client.resolveSessionClientSide(base, null, printedRef);
      outcomes.push({ version, stableRef, printedRef, targetRow, cliResolvedId: resolved.id, cliResolvedName: resolved.session.name, serverResolvedId: direct.session.id, fallbackResolvedId: clientSide.id, listOutput: listed });
    }
    assert.equal(outcomes[0].printedRef, encoded);
    assert.equal(outcomes[0].cliResolvedId, encoded);
    assert.equal(outcomes[1].printedRef, 'route-hi');
    assert.equal(outcomes[1].cliResolvedId, native);
    const result = { baseline: 'dc4ae84568fda976cfb136082b1dda405ccf54d8', final: 'e694d8948eecaf85c02b21db0185035fff57a501', native, encoded, admittedCatalogRows: catalog.previous, capabilities: host.capabilities, outcomes, conclusion: 'Actual first-party discovery admits both fixture identities; baseline installed CLI prints a handle resolving to OMP target, R11 installed CLI prints route-hi resolving to Pi peer. Same wrong target via product and client-side resolver. No lifecycle/control operation executed.' };
    fs.writeFileSync('/tmp/r11-retarget-result.json', JSON.stringify(result, null, 2));
    console.log(JSON.stringify(result, null, 2));
  } finally {
    server.close();
    fs.rmSync(home, { recursive: true, force: true });
  }
})().catch(error => { console.error(error); process.exitCode = 1; });

