const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const http = require('node:http');
const assert = require('node:assert/strict');
const run = require('node:util').promisify(require('node:child_process').execFile);
const root = process.cwd();
require(path.join(root, 'test/test-env')).applyTestEnv();
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'r11-corrected-'));
Object.assign(process.env, { HOME: home, TMUX_TMPDIR: path.join(home, 'tmux'), PI_DISH_INDEX_SYNC_BUDGET: '1000' });
fs.mkdirSync(process.env.TMUX_TMPDIR);
const uuid = '01a070d2-43fb-7360-aaba-a4ddf8d1deb0';
const encode = native => '~sk1_' + Buffer.from(JSON.stringify(['omp', native])).toString('base64url');
const fixtures = [
  ['pi', 'route-hit', 'Pi alias owner'], ['omp', 'route-hit', 'OMP alias collision'],
  ['omp', `2026-09-05T09-07-03-291Z_${uuid}`, 'Shared UUID morning'],
  ['omp', `2026-09-06T09-07-03-291Z_${uuid}`, 'Shared UUID next day'],
  ['omp', '2026-09-07T09-07-03-291Z_01a07264-131e-74a7-979a-1e763bf12b97', 'Ordinary UUID'],
  ['omp', 'shadowed', 'Short alias'], ['omp', 'shadowed-long', 'Extended alias'],
].map(([harness, native, name]) => ({ harness, native, name, id: harness === 'pi' ? native : encode(native) }));
for (const fixture of fixtures) {
  const dir = path.join(home, `.${fixture.harness}`, 'agent/sessions/project');
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, fixture.native + '.jsonl'), [
    { type: 'session', version: 3, id: fixture.native, cwd: home, timestamp: '2026-09-07T09:07:03.291Z' },
    { type: 'session_info', name: fixture.name },
    { type: 'message', id: 'u1', message: { role: 'user', content: [{ type: 'text', text: fixture.name }], timestamp: '2026-09-07T09:07:04.000Z' } },
  ].map(JSON.stringify).join('\n') + '\n');
}
for (const version of ['before','corrected']) {
  const skills = path.join(home, version, 'skills');
  fs.mkdirSync(path.join(skills, 'lib'), { recursive: true });
  fs.mkdirSync(path.join(skills, 'pi-dish-sessions/scripts'), { recursive: true });
  fs.copyFileSync(version === 'before' ? '/tmp/r11-baseline-client.js' : path.join(root, 'skills/lib/pi-dish-client.js'), path.join(skills, 'lib/pi-dish-client.js'));
  fs.copyFileSync(path.join(root, 'skills/pi-dish-sessions/scripts/pi-dish-sessions.js'), path.join(skills, 'pi-dish-sessions/scripts/pi-dish-sessions.js'));
  fs.symlinkSync(path.join(skills, 'pi-dish-sessions'), path.join(home, version, 'installed-skill'));
}
const server = require(path.join(root, 'server'));
let legacy;
(async () => {
  if (!server.listening) await new Promise(resolve => server.once('listening', resolve));
  const base = `http://127.0.0.1:${server.address().port}`;
  let catalog;
  for (let i = 0; i < 100; i++) {
    catalog = await (await fetch(base + '/api/sessions')).json();
    if (!catalog.indexing && catalog.previous.length === fixtures.length) break;
    await new Promise(resolve => setTimeout(resolve, 50));
  }
  assert.deepEqual(catalog.previous.map(s => s.id).sort(), fixtures.map(s => s.id).sort());
  const identity = await (await fetch(base + '/api/host')).json();
  legacy = http.createServer(async (req, res) => {
    const response = await fetch(base + req.url);
    const data = await response.json();
    if (req.url === '/api/hosts') for (const host of data.hosts) host.capabilities = {};
    res.writeHead(response.status, { 'content-type': 'application/json' });
    res.end(JSON.stringify(data));
  });
  await new Promise(resolve => legacy.listen(0, '127.0.0.1', resolve));
  const legacyBase = `http://127.0.0.1:${legacy.address().port}`;
  const outcomes = [];
  for (const version of ['before','corrected']) {
    const cli = path.join(home, version, 'installed-skill/scripts/pi-dish-sessions.js');
    const client = require(path.join(home, version, 'skills/lib/pi-dish-client.js'));
    const invoke = (args, endpoint = base) => run(process.execPath, [cli, ...args, '--url', endpoint], { env: process.env, cwd: home });
    const listed = (await invoke(['list'])).stdout.split('\n').map(line => line.split('\t'));
    for (const fixture of fixtures) {
      const row = listed.find(columns => columns[2] === fixture.name);
      assert.ok(row, fixture.name);
      const ref = row[0];
      assert.equal(client.stableSessionRef(fixture.id, catalog.previous.map(s => s.id)), ref);
      const product = JSON.parse((await invoke(['resolve', ref, '--json'])).stdout);
      const fallback = JSON.parse((await invoke(['resolve', ref, '--json'], legacyBase)).stdout);
      assert.equal(product.id, fixture.id);
      assert.equal(fallback.id, fixture.id);
      const serverReply = await (await fetch(base + '/api/sessions/resolve?id=' + encodeURIComponent(fixture.id))).json();
      const serverRoundTrip = await (await fetch(base + '/api/sessions/resolve?id=' + encodeURIComponent(serverReply.ref))).json();
      assert.equal(serverRoundTrip.session.id, fixture.id);
      if (fixture.name === 'Ordinary UUID') assert.equal(ref, '01a07264');
      if (fixture.name === 'OMP alias collision') assert.equal(ref, fixture.id);
      outcomes.push({ version, name: fixture.name, id: fixture.id, printedRef: ref, productId: product.id, fallbackId: fallback.id, serverRef: serverReply.ref, serverRoundTripId: serverRoundTrip.session.id });
    }
    for (const endpoint of [base, legacyBase]) {
      await assert.rejects(invoke(['resolve', uuid], endpoint), e => e.code === 1 && /ambiguous/.test(e.stderr));
      await assert.rejects(invoke(['resolve', `${identity.hostId}:01a07264`], endpoint), e => e.code === 1 && /Session not found/.test(e.stderr));
    }
  }
  assert.equal((await fetch(base + '/api/sessions/resolve?id=' + uuid)).status, 409);
  const result = { base, legacyBase, home, fixtures, outcomes, summary: '7 first-party admitted rows, baseline+corrected installed symlink CLI lists and 28 product/fallback resolutions preserve identity; 14 server ref roundtrips; ordinary UUID unchanged; 4 shared UUID ambiguity failures and 4 provenance-prefix misses; no native launch or control request.' };
  fs.writeFileSync('/tmp/r11-corrected-runtime-result.json', JSON.stringify(result, null, 2));
  console.log('R11_CORRECTED_READY ' + JSON.stringify(result));
})().catch(error => { console.error(error); legacy?.close(); server.close(); process.exitCode = 1; });
process.on('SIGTERM', () => { legacy?.close(); server.close(); fs.rmSync(home, { recursive: true, force: true }); setTimeout(() => process.exit(0), 200).unref(); });
